<template><StatusPanel v-if="loading" class="container section">Загружаем ресторан…</StatusPanel><section v-else-if="error" class="container section"><StatusPanel kind="error">{{ error }} <RouterLink to="/">К списку ресторанов</RouterLink></StatusPanel></section><template v-else-if="restaurant"><section class="restaurant-hero" :style="{ backgroundImage: `linear-gradient(0deg, rgba(31,35,34,.82), rgba(31,35,34,.18)), url(${restaurant.image})` }"><div class="container"><p class="eyebrow light">{{ restaurant.cuisine }} · {{ restaurant.district }}</p><h1>{{ restaurant.name }}</h1><p>{{ restaurant.address }} · {{ restaurant.metro }} · ★ {{ restaurant.rating }}</p></div></section><section class="container section detail-grid"><div><p class="lead">{{ restaurant.description }}</p><h2>Меню</h2><div v-if="menu.length"><div v-for="item in menu" :key="item.id" class="menu-row"><div><strong>{{ item.name }}</strong><p class="meta">{{ item.description }}</p></div><b>{{ item.price }}</b></div></div><p v-else class="meta">Меню пока не добавлено.</p><h2>Демонстрационные отзывы</h2><article v-for="review in reviews" :key="review.id" class="review"><strong>{{ review.author }} · ★ {{ review.rating }}</strong><p>{{ review.text }}</p></article></div><aside class="booking-card"><p class="eyebrow">Учебная бронь</p><h2>Выберите время</h2><p v-if="!isAuthenticated" class="notice">Чтобы подтвердить бронь, <RouterLink :to="{name:'login',query:{next:$route.fullPath}}">войдите в учебный профиль</RouterLink>.</p><BookingForm v-else :busy="saving" :error="formError" @submit="reserve" /></aside></section></template></template><script setup>import { onMounted, ref, watch } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import BookingForm from '../components/BookingForm.vue'; import StatusPanel from '../components/StatusPanel.vue'; import { bookingApi, restaurantApi } from '../composables/useApi'; import { useSession } from '../composables/useSession'; const route=useRoute(), router=useRouter(); const {isAuthenticated}=useSession(); const restaurant=ref(null), menu=ref([]), reviews=ref([]), loading=ref(true), error=ref(''), saving=ref(false), formError=ref(''); async function load(){loading.value=true; error.value=''; try { const id=route.params.id; const [r,m,rv]=await Promise.all([restaurantApi.one(id),restaurantApi.menu(id),restaurantApi.reviews(id)]); restaurant.value=r;menu.value=m;reviews.value=rv; } catch(e){error.value=e.message;} finally{loading.value=false;}} async function reserve(payload){saving.value=true;formError.value='';try{await bookingApi.create({...payload,restaurantId:restaurant.value.id}); router.push({name:'bookings',query:{created:'1'}});}catch(e){formError.value=e.message;}finally{saving.value=false;}} onMounted(load); watch(()=>route.params.id,load);</script>
